  if (now < cert.notBefore) return "not yet valid";
  if (now > cert.notAfter) return "expired";
  const daysLeft = Math.floor((cert.notAfter - now) / DAY);
  return daysLeft < 30 ? `renew soon (${daysLeft} days)` : "ok";
}

