function certCovers(names, host) {
  const h = host.toLowerCase();
  return names.some((name) => {
    const n = name.toLowerCase();
    if (!n.startsWith("*.")) return n === h;
    const rest = n.slice(1);
    return h.endsWith(rest) && !h.slice(0, -rest.length).includes(".") && h.length > rest.length;
  });
}

const names = ["shop.example", "*.shop.example"];
for (const host of ["shop.example", "API.shop.example", "a.b.shop.example", "shop.example.net", "evilshop.example"]) {
  console.log(host, certCovers(names, host));
