function signingKid(keys) {
  const active = Object.entries(keys).filter(([, key]) => key.status === "active").map(([kid]) => kid);
  if (active.length !== 1) throw new Error(`expected exactly one active key, found ${active.length}`);
  return active[0];
}

console.log(signingKid({ k1: { status: "verify-only" }, k2: { status: "active" } }));
