function expiringSoon(certs, now, days) {
  const limit = now + days * 86_400_000;
  return certs
    .filter((cert) => cert.notAfter < limit)
    .toSorted((a, b) => a.notAfter - b.notAfter)
    .map((cert) => cert.host);
}

